#!/bin/sh
# shellcheck shell=bash
# Resolve which command formats or lints a file for a format or lint plugin,
# and run it. The contract is the check-placement convention's "Record path"
# section; the record is the ecosystem-commands contract's
# .claude/ecosystems/<id>.yaml.
#
# SINGLE SOURCE OF TRUTH: lib/git-hooks/resolve-tool.sh at the marketplace repo
# root. Plugin copies are generated by scripts/sync-shared-copies.sh.
#
# Sourced by bash (3.2 or later). The plugin sets, before calling:
#   RT_PLUGIN   the plugin name
#   RT_IDS      the ecosystem ids it binds, space-separated
# and may define the adapter it ships:
#   rt_adapter <concern> <file> <root>     0 when the adapter governs <file>;
#                                          sets RT_ADAPTER, RT_SCRIPT, RT_DIR,
#                                          RT_TOOL, RT_BIN, RT_INSTALL and
#                                          optionally RT_CONFIGS
#   rt_adapter_in_repo <concern> <root>    0 when the adapter's config is in the
#                                          repository; sets RT_ADAPTER, RT_TOOL, RT_BIN
#
#   rt_resolve <file> <concern> <root>   concern is format (the record's fix-cmd)
#                                        or lint (lint-cmd). Sets:
#     RT_SOURCE  record:<id> | adapter:<name> | none | ambiguous | unapproved | parse-error
#     RT_SCRIPT  the command, <files> replaced by "$@" (never spliced)
#     RT_DIR     where it runs: the record's project-discovery root, the
#                adapter's directory, else the repository root
#     RT_TOOL    the missing-tool key: the record's first tool-pin key, else the
#                basename of the command's first word
#     RT_BIN     the command's first word, $REPO_ROOT expanded
#     RT_REASON  why, for a source that runs nothing, or whole-tree:<id> when
#                the record's key has no <files> and the next rung was taken
#   rt_forget                drop the cached record and approval reads, after
#                            a record or a file it names changed
#   rt_run <files...>        run RT_SCRIPT as `sh -c "$RT_SCRIPT" sh <files...>`
#                            from RT_DIR with REPO_ROOT set, in chunks that
#                            stay under the Windows command-line limit; returns
#                            the highest exit status
#   rt_lint <files...>       rt_run, then rt_normalize its output: each
#                            "<path>:<line>[:<col>]: <message>" line printed as
#                            repo-relative "<path>:<line>: <message>"; returns
#                            3, showing the output on stderr, when the command
#                            exits non-zero and no finding parsed
#   rt_group / rt_use        resolve many files and group them by command
#   rt_found <bin>           0 when the command's first word is runnable
#   rt_print <concern> <root> [<file>...]
#                            one TSV row for the repository, or one per file:
#                            plugin, concern, source, tool, approval (accepted
#                            | approved | unapproved | n/a), found (yes | no |
#                            n/a), detail (the adapter's RT_DETAIL, such as the
#                            config that governs the file, or why nothing
#                            resolved). Executes nothing.
#   resolve-tool.sh --approve <id> [<root>]   record a per-clone approval of
#                            the id's current record (attended setup only)
#
# Layers, key by key (ecosystem-commands "File layout and resolution"):
# ~/.claude/ecosystems/<id>.yaml, then .claude/ecosystems/<id>.yaml, then
# <id>.local.yaml. A key from the team file, or from a .local file git tracks,
# is repository content: it runs only when that file, and every tracked file
# its command names, matches the default branch (refs/remotes/origin/HEAD, read
# locally), or when a per-clone approval of exactly those bytes sits under
# <git common dir>/claude-ecosystems/approved/. Anything else is unapproved and
# runs nothing; it never falls through to the adapter. A record key with no
# <files> is not a hook opt-in, so that concern takes the next rung.

# shellcheck disable=SC2034 # the RT_* results are read by the plugin that sources this file
RT_HERE="${BASH_SOURCE[0]%/*}"
[[ "$RT_HERE" == "${BASH_SOURCE[0]}" ]] && RT_HERE=.
RT_AWK="$RT_HERE/yaml-subset.awk"
[[ -f "$RT_AWK" ]] || RT_AWK="$RT_HERE/../yaml-subset.awk"
RT_PLUGIN="${RT_PLUGIN:-}"
RT_IDS="${RT_IDS:-}"
RT_ROOT=""
RT__LOADED=""
RT__ARGMAX=24000

rt__reset() {
  RT_SOURCE=none RT_SCRIPT="" RT_DIR="" RT_TOOL="" RT_BIN="" RT_INSTALL=""
  RT_REASON="" RT_ID="" RT_ADAPTER="" RT_APPROVAL=n/a RT_CONFIGS="" RT_DETAIL=""
}
rt__reset

rt_forget() { RT__LOADED=""; }

rt__key() { [[ "$1" == lint ]] && RT__KEY=lint-cmd || RT__KEY=fix-cmd; }

# rt__load <root> <id>: read the three layers into RT__K/RT__V/RT__L (key,
# value, layer: user | team | local | tracked-local). Returns 1 with RT__ERR
# set on a parse error. Cached for the last root and id.
rt__load() {
  local root="$1" id="$2" layer file out line k v i j has
  [[ "$RT__LOADED" == "$root|$id" ]] && return "$RT__STATUS"
  RT__LOADED="$root|$id" RT__STATUS=0 RT__ERR="" RT__APPR_format="" RT__APPR_lint=""
  RT__K=() RT__V=() RT__L=()
  for layer in user team local; do
    case "$layer" in
    user) file="${HOME:-}/.claude/ecosystems/$id.yaml" ;;
    team) file="$root/.claude/ecosystems/$id.yaml" ;;
    *) file="$root/.claude/ecosystems/$id.local.yaml" ;;
    esac
    [[ -f "$file" ]] || continue
    if [[ "$layer" == local && -n "$(git -C "$root" ls-files -- ".claude/ecosystems/$id.local.yaml" 2>/dev/null)" ]]; then
      layer="tracked-local"
    fi
    if ! out="$(awk -f "$RT_AWK" "$file" 2>&1)"; then
      line="${out##*$'\n'}"
      IFS=$'\t' read -r _ i v <<<"$line"
      RT__ERR="${file#"$root/"} line ${i:-?}: ${v:-unreadable}"
      RT__STATUS=1
      return 1
    fi
    has=0
    [[ "$out" == *$'\n'globs.* || "$out" == globs.* ]] && has=1
    if ((has)); then
      for i in "${!RT__K[@]}"; do
        [[ "${RT__K[i]}" == globs.* ]] && unset 'RT__K[i]' 'RT__V[i]' 'RT__L[i]'
      done
    fi
    while IFS=$'\t' read -r k v; do
      [[ -n "$k" ]] || continue
      j=""
      for i in "${!RT__K[@]}"; do
        [[ "${RT__K[i]}" == "$k" ]] && j="$i" && break
      done
      if [[ -n "$j" ]]; then
        RT__V[j]="$v" RT__L[j]="$layer"
      else
        RT__K+=("$k") RT__V+=("$v") RT__L+=("$layer")
      fi
    done <<<"$out"
  done
  return 0
}

# rt__get <key>: sets RT__GV and RT__GL to the merged value and its layer;
# returns 1 when unset or null.
rt__get() {
  local i
  RT__GV="" RT__GL=""
  for i in "${!RT__K[@]}"; do
    if [[ "${RT__K[i]}" == "$1" ]]; then
      RT__GV="${RT__V[i]}" RT__GL="${RT__L[i]}"
      [[ -n "$RT__GV" && "$RT__GV" != null && "$RT__GV" != "~" ]]
      return
    fi
  done
  return 1
}

# rt__globs_match <rel>: 0 when a merged globs entry matches <rel>. A pattern
# without / matches the base name; ** spans directories.
rt__globs_match() {
  local i p base="${1##*/}"
  for i in "${!RT__K[@]}"; do
    [[ "${RT__K[i]}" == globs.* ]] || continue
    p="${RT__V[i]}"
    p="${p//\*\*\//}"
    if [[ "$p" == */* ]]; then
      # shellcheck disable=SC2053 # the record's glob
      [[ "$1" == $p ]] && return 0
    else
      # shellcheck disable=SC2053 # the record's glob
      [[ "$base" == $p ]] && return 0
    fi
  done
  return 1
}

# rt__words <command>: sets RT__W to the command's words, quotes dropped.
rt__words() {
  local w
  RT__W=()
  set -f
  for w in $1; do
    w="${w//\"/}"
    RT__W+=("${w//\'/}")
  done
  set +f
}

# rt__refs <command> <root>: sets RT__REFS to the repository files the
# command names, repo-relative: a word naming a file after $REPO_ROOT/ and a
# --opt= prefix are dropped.
rt__refs() {
  local w placeholder='<files>'
  RT__REFS=()
  rt__words "$1"
  for w in ${RT__W[@]+"${RT__W[@]}"}; do
    w="${w#\$\{REPO_ROOT\}/}"
    w="${w#\$REPO_ROOT/}"
    [[ "$w" == --*=* ]] && w="${w#*=}"
    case "$w" in
    "" | /* | *..* | *"$placeholder"*) continue ;;
    *) ;;
    esac
    [[ -f "$2/$w" ]] && RT__REFS+=("$w")
  done
}

# rt__common <root>: sets RT__COMMON (the git common dir, POSIX spelling on
# Git Bash) and RT__TIP (the default branch's commit, or empty), in one git call.
rt__common() {
  local out
  out="$(git -C "$1" rev-parse --path-format=absolute --git-common-dir --verify --quiet 'refs/remotes/origin/HEAD^{commit}' 2>/dev/null)"
  RT__COMMON="${out%%$'\n'*}" RT__TIP=""
  [[ "$out" == *$'\n'* ]] && RT__TIP="${out##*$'\n'}"
  if [[ "$RT__COMMON" == [A-Za-z]:[\\/]* ]] && command -v cygpath >/dev/null 2>&1; then
    RT__COMMON="$(cygpath -u "$RT__COMMON" 2>/dev/null)" || RT__COMMON=""
  fi
}

# rt__approval <root> <id> <concern>: sets RT_APPROVAL (accepted | approved |
# unapproved) for the repository layers behind the concern's merged command,
# and RT__SIG, the approval key of their current bytes. Cached per concern.
rt__approval() {
  local root="$1" id="$2" concern="$3" cache="RT__APPR_$3" cmd p h line type blob path
  if [[ -n "${!cache}" ]]; then
    RT_APPROVAL="${!cache%%|*}" RT__SIG="${!cache#*|}"
    return
  fi
  rt__key "$concern"
  rt__get "$RT__KEY"
  cmd="$RT__GV"
  local paths=() hashes=() keep=() missing=()
  [[ -f "$root/.claude/ecosystems/$id.yaml" ]] && paths+=(".claude/ecosystems/$id.yaml")
  for p in "${RT__L[@]}"; do
    [[ "$p" == tracked-local ]] && paths+=(".claude/ecosystems/$id.local.yaml") && break
  done
  local nlayers=${#paths[@]}
  rt__refs "$cmd" "$root"
  paths+=(${RT__REFS[@]+"${RT__REFS[@]}"})
  rt__common "$root"
  while IFS= read -r h; do
    hashes+=("$h")
  done < <(git -C "$root" hash-object -- "${paths[@]}" 2>/dev/null)
  RT_APPROVAL=unapproved
  local i ok=1 tree=$'\n'
  if [[ -n "$RT__TIP" ]]; then
    while IFS=$'\t' read -r line path; do
      read -r _ type blob <<<"$line"
      [[ "$type" == blob ]] && tree+="$path"$'\t'"$blob"$'\n'
    done < <(git -C "$root" ls-tree "$RT__TIP" -- "${paths[@]}" 2>/dev/null)
  fi
  for i in "${!paths[@]}"; do
    p="${paths[i]}" h="${hashes[i]:-}"
    if [[ "$tree" == *$'\n'"$p"$'\t'* ]]; then
      keep+=("$p"$'\t'"$h")
      [[ "$tree" == *$'\n'"$p"$'\t'"$h"$'\n'* ]] || ok=0
    elif ((i < nlayers)); then
      keep+=("$p"$'\t'"$h")
      ok=0
    else
      missing+=("$i")
    fi
  done
  # A named file the default branch lacks counts only when git tracks it: an
  # untracked file is the user's own install, never content a clone brought.
  if ((${#missing[@]})); then
    local tracked=$'\n' missing_paths=()
    for i in "${missing[@]}"; do
      missing_paths+=("${paths[i]}")
    done
    while IFS= read -r p; do
      tracked+="$p"$'\n'
    done < <(git -C "$root" ls-files -- "${missing_paths[@]}" 2>/dev/null)
    for i in "${missing[@]}"; do
      if [[ "$tracked" == *$'\n'"${paths[i]}"$'\n'* ]]; then
        keep+=("${paths[i]}"$'\t'"${hashes[i]:-}")
        ok=0
      fi
    done
  fi
  [[ -n "$RT__TIP" ]] || ok=0
  RT__SIG=""
  if ((ok)); then
    RT_APPROVAL=accepted
  elif [[ -n "$RT__COMMON" ]]; then
    RT__SIG="$(printf '%s\n' "$id" "${keep[@]}" | git hash-object --stdin 2>/dev/null)"
    [[ -n "$RT__SIG" && -e "$RT__COMMON/claude-ecosystems/approved/$RT__SIG" ]] && RT_APPROVAL=approved
  fi
  printf -v "$cache" '%s|%s' "$RT_APPROVAL" "$RT__SIG"
}

# rt__record <id> <concern> <root>: the record's command for the concern, set
# into RT_* (RT_SOURCE record:<id>, or unapproved).
rt__record() {
  local id="$1" concern="$2" root="$3" i first
  RT_ID="$id"
  RT_SCRIPT="${RT__GV//<files>/\"\$@\"}"
  RT_INSTALL=""
  rt__get install-hint && RT_INSTALL="$RT__GV"
  RT_TOOL=""
  for i in "${!RT__K[@]}"; do
    [[ "${RT__K[i]}" == tool-pin.* ]] && RT_TOOL="${RT__K[i]#tool-pin.}" && break
  done
  rt__words "$RT_SCRIPT"
  first="${RT__W[0]:-}"
  RT_BIN="${first/#\$\{REPO_ROOT\}/$root}"
  RT_BIN="${RT_BIN/#\$REPO_ROOT/$root}"
  [[ -n "$RT_TOOL" ]] || RT_TOOL="${first##*/}"
  RT_SOURCE="record:$id"
  case "$RT__L_CMD" in
  team | tracked-local)
    rt__approval "$root" "$id" "$concern"
    [[ "$RT_APPROVAL" == unapproved ]] && RT_SOURCE=unapproved RT_SCRIPT="" \
      RT_REASON="the $id record differs from the default branch and has no approval for this clone"
    ;;
  *) RT_APPROVAL=n/a ;;
  esac
}

# rt__project_dir <rel> <root>: the nearest directory at or above <rel>'s that
# holds a project-discovery pattern, else the root.
rt__project_dir() {
  local dir i p hit
  RT_DIR="$2"
  dir="${1%/*}"
  [[ "$dir" == "$1" ]] && dir=""
  while :; do
    for i in "${!RT__K[@]}"; do
      [[ "${RT__K[i]}" == project-discovery.* ]] || continue
      p="${RT__V[i]}"
      for hit in "$2${dir:+/$dir}"/$p; do
        [[ -e "$hit" ]] && RT_DIR="$2${dir:+/$dir}" && return
      done
    done
    [[ -n "$dir" ]] || return
    [[ "$dir" == */* ]] && dir="${dir%/*}" || dir=""
  done
}

rt_resolve() { # <file> <concern> <root>
  local file="$1" concern="$2" root="$3" rel id key whole="" hits=0 hit_id="" hit_cmd="" hit_layer=""
  rt__reset
  RT_ROOT="$root"
  rel="${file#"$root/"}"
  rt__key "$concern"
  key="$RT__KEY"
  for id in $RT_IDS; do
    if ! rt__load "$root" "$id"; then
      RT_SOURCE=parse-error RT_REASON="$RT__ERR"
      return 0
    fi
    rt__globs_match "$rel" || continue
    if rt__get enabled && [[ "$RT__GV" == false ]]; then
      RT_REASON="disabled:$id"
      return 0
    fi
    rt__get "$key" || continue
    if [[ "$RT__GV" != *"<files>"* ]]; then
      whole="$id"
      continue
    fi
    if ((hits)) && [[ "$RT__GV" != "$hit_cmd" ]]; then
      RT_SOURCE=ambiguous RT_REASON="records $hit_id and $id both bind ${rel##*/}"
      return 0
    fi
    hits=1 hit_id="$id" hit_cmd="$RT__GV" hit_layer="$RT__GL"
  done
  if ((hits)); then
    rt__load "$root" "$hit_id"
    RT__GV="$hit_cmd" RT__L_CMD="$hit_layer"
    rt__record "$hit_id" "$concern" "$root"
    [[ "$RT_SOURCE" == unapproved ]] || rt__project_dir "$rel" "$root"
    return 0
  fi
  if declare -F rt_adapter >/dev/null && rt_adapter "$concern" "$file" "$root"; then
    RT_SOURCE="adapter:$RT_ADAPTER"
  fi
  [[ -n "$whole" ]] && RT_REASON="whole-tree:$whole"
  return 0
}

# rt_group <concern> <root> <files...>: rt_resolve each file and group the
# files that resolve to one command. Sets RT_GN, the group count, and per group
# i the RT_G_* arrays rt_use reads; RT_GFAIL holds one line per file whose
# record is a parse error or ambiguous; RT_GOTHER lists the files no record
# binds (adapter or none). Files resolving to nothing are in no group.
rt_group() {
  local concern="$1" root="$2" f key i found
  shift 2
  RT_GN=0 RT_GFAIL=""
  RT_G_KEY=() RT_G_SOURCE=() RT_G_SCRIPT=() RT_G_DIR=() RT_G_TOOL=() RT_G_BIN=()
  RT_G_INSTALL=() RT_G_CONFIGS=() RT_G_ID=() RT_G_FILES=() RT_GOTHER=()
  for f in "$@"; do
    rt_resolve "$f" "$concern" "$root"
    [[ "$RT_SOURCE" == adapter:* || "$RT_SOURCE" == none ]] && RT_GOTHER+=("$f")
    case "$RT_SOURCE" in
    parse-error | ambiguous)
      [[ "$RT_GFAIL" == *"$RT_REASON"* ]] || RT_GFAIL+="$RT_REASON"$'\n'
      continue
      ;;
    record:* | adapter:*) ;;
    *) continue ;;
    esac
    key="$RT_SOURCE|$RT_DIR|$RT_BIN|$RT_SCRIPT"
    found=""
    for i in "${!RT_G_KEY[@]}"; do
      [[ "${RT_G_KEY[i]}" == "$key" ]] && found="$i" && break
    done
    if [[ -z "$found" ]]; then
      found=$RT_GN
      RT_GN=$((RT_GN + 1))
      RT_G_KEY[found]="$key" RT_G_SOURCE[found]="$RT_SOURCE" RT_G_SCRIPT[found]="$RT_SCRIPT"
      RT_G_DIR[found]="$RT_DIR" RT_G_TOOL[found]="$RT_TOOL" RT_G_BIN[found]="$RT_BIN"
      RT_G_INSTALL[found]="$RT_INSTALL" RT_G_CONFIGS[found]="$RT_CONFIGS" RT_G_ID[found]="$RT_ID"
      RT_G_FILES[found]=""
    fi
    RT_G_FILES[found]+="$f"$'\x1f'
  done
}

# rt_use <i>: set RT_* to group i, and RT_FILES to its files.
rt_use() {
  local f rest
  RT_SOURCE="${RT_G_SOURCE[$1]}" RT_SCRIPT="${RT_G_SCRIPT[$1]}" RT_DIR="${RT_G_DIR[$1]}"
  RT_TOOL="${RT_G_TOOL[$1]}" RT_BIN="${RT_G_BIN[$1]}" RT_INSTALL="${RT_G_INSTALL[$1]}"
  RT_CONFIGS="${RT_G_CONFIGS[$1]}" RT_ID="${RT_G_ID[$1]}"
  RT_FILES=()
  rest="${RT_G_FILES[$1]}"
  while [[ -n "$rest" ]]; do
    f="${rest%%$'\x1f'*}"
    rest="${rest#*$'\x1f'}"
    RT_FILES+=("$f")
  done
}

# rt__arg <file>: sets RT__A to <file> as RT_DIR sees it; a leading dash gains ./ so no tool
# reads a file name as an option.
rt__arg() {
  local abs="$1"
  [[ "$abs" == /* || "$abs" == [A-Za-z]:[\\/]* ]] || abs="$PWD/$abs"
  [[ "$abs" == "$RT_DIR/"* ]] && abs="${abs#"$RT_DIR/"}"
  [[ "$abs" == -* ]] && abs="./$abs"
  RT__A="$abs"
}

rt_run() { # <files...>
  local f a size=0 status=0 rc chunk=()
  local args=()
  for f in "$@"; do
    rt__arg "$f"
    args+=("$RT__A")
  done
  for a in "${args[@]}" ""; do
    if [[ -z "$a" ]] || ((size + ${#a} + 1 > RT__ARGMAX && ${#chunk[@]})); then
      if ((${#chunk[@]})); then
        (cd "$RT_DIR" && REPO_ROOT="$RT_ROOT" RT_BIN="$RT_BIN" sh -c "$RT_SCRIPT" sh "${chunk[@]}")
        rc=$?
        ((rc > status)) && status=$rc
      fi
      chunk=() size=0
    fi
    [[ -n "$a" ]] && chunk+=("$a") && size=$((size + ${#a} + 1))
  done
  return "$status"
}

# rt__finding <line>: sets RT__F to the line as a repo-relative finding, or
# to empty when the line is not one.
rt__finding() {
  local line="${1%$'\r'}" drive="" path rel
  RT__F=""
  if [[ "$line" =~ ^[A-Za-z]:[\\/] ]]; then
    drive="${line:0:2}" line="${line:2}"
  fi
  [[ "$line" =~ ^([^:]+):([0-9]+)(:[0-9]+)?:[[:space:]]?(.*)$ ]] || return 0
  path="$drive${BASH_REMATCH[1]}"
  path="${path//\\//}"
  path="${path#./}"
  if [[ "$path" == /* || "$path" == [A-Za-z]:/* ]]; then
    rel="${path#"$RT_ROOT/"}"
  elif [[ "$RT_DIR" == "$RT_ROOT" || -z "$RT_DIR" ]]; then
    rel="$path"
  else
    rel="${RT_DIR#"$RT_ROOT/"}/$path"
  fi
  RT__F="$rel:${BASH_REMATCH[2]}: ${BASH_REMATCH[4]}"
}

# rt_normalize <output file> <status>: print the file's findings as
# repo-relative "<path>:<line>: <message>" lines; returns 3, showing the
# output on stderr, when <status> is non-zero and no finding parsed.
rt_normalize() {
  local line found=0
  while IFS= read -r line || [[ -n "$line" ]]; do
    rt__finding "$line"
    [[ -n "$RT__F" ]] && found=1 && printf '%s\n' "$RT__F"
  done <"$1"
  if (($2 != 0 && !found)); then
    printf '%s: %s exited %s and reported no <path>:<line> finding, so the change was not checked:\n' \
      "${RT_PLUGIN:-lint}" "${RT_TOOL:-the linter}" "$2" >&2
    cat "$1" >&2
    return 3
  fi
  return 0
}

rt_lint() { # <files...>
  local out status tmp="${CHECKS_TMP:-}" own=""
  if [[ -z "$tmp" ]]; then
    tmp="$(mktemp -d "${TMPDIR:-/tmp}/rt.XXXXXX")" || return 3
    own=1
  fi
  out="$tmp/rt-lint.$$"
  rt_run "$@" >"$out" 2>&1
  rt_normalize "$out" "$?"
  status=$?
  rm -f "$out"
  [[ -n "$own" ]] && rm -rf "$tmp"
  return "$status"
}

rt_found() { # <bin>
  if [[ "$1" == */* ]]; then
    [[ -x "$1" ]]
  else
    command -v "$1" >/dev/null 2>&1
  fi
}

# rt_require: a git-hook entry's missing-tool rule (check-lib.sh's
# checks_require_tool) for the resolved command's first word, keyed by RT_TOOL.
rt_require() {
  local install="${RT_INSTALL:-the command the ${RT_ID:-} record names}"
  rt_found "$RT_BIN" && return 0
  if checks_skip_listed "$RT_TOOL"; then
    printf 'SKIPPED: %s (missing)\n' "$RT_TOOL" >&2
    exit 0
  fi
  if checks_is_agent; then
    printf 'FAIL: %s missing. Install: %s\n' "$RT_TOOL" "$install" >&2
    printf 'To skip only while %s is missing: git -c checks.skipmissing=%s %s ...\n' "$RT_TOOL" "$RT_TOOL" "$(checks_git_verb)" >&2
    exit 1
  fi
  printf 'NOTICE: %s missing, so this check did not run. Install: %s\n' "$RT_TOOL" "$install" >&2
  exit 0
}

rt_print() { # <concern> <root> [<file>...]
  local concern="$1" root="$2" id key whole="" found f source tool approval
  if (($# > 2)); then
    shift 2
    for f in "$@"; do
      rt_resolve "$f" "$concern" "$root"
      source="$RT_SOURCE" tool="$RT_TOOL" approval="$RT_APPROVAL" found=n/a
      [[ "$source" == unapproved ]] && source="record:$RT_ID"
      case "$source" in
      record:* | adapter:*)
        found=no
        rt_found "$RT_BIN" && found=yes
        ;;
      *) tool="" ;;
      esac
      printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$RT_PLUGIN" "$concern" "$source" "$tool" "$approval" "$found" "${RT_DETAIL:-$RT_REASON}"
    done
    return 0
  fi
  rt__reset
  RT_ROOT="$root"
  rt__key "$concern"
  key="$RT__KEY"
  for id in $RT_IDS; do
    if ! rt__load "$root" "$id"; then
      printf '%s\t%s\tparse-error\t\tn/a\tn/a\t%s\n' "$RT_PLUGIN" "$concern" "$RT__ERR"
      return 0
    fi
    rt__get "$key" || continue
    if [[ "$RT__GV" != *"<files>"* ]]; then
      whole="$id"
      continue
    fi
    RT__L_CMD="$RT__GL"
    rt__record "$id" "$concern" "$root"
    found=no
    rt_found "$RT_BIN" && found=yes
    [[ "$RT_SOURCE" == unapproved ]] && RT_SOURCE="record:$id"
    printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$RT_PLUGIN" "$concern" "$RT_SOURCE" "$RT_TOOL" "$RT_APPROVAL" "$found" ""
    return 0
  done
  local detail="" ok=1
  [[ -n "$whole" ]] && detail="the $whole record's $key names no <files>, so hooks do not run it"
  declare -F rt_adapter_in_repo >/dev/null && rt_adapter_in_repo "$concern" "$root" && ok=0
  [[ -n "$RT_DETAIL" ]] && detail="${detail:+$detail; }$RT_DETAIL"
  if ((ok == 0)); then
    found=no
    rt_found "$RT_BIN" && found=yes
    printf '%s\t%s\tadapter:%s\t%s\tn/a\t%s\t%s\n' "$RT_PLUGIN" "$concern" "$RT_ADAPTER" "$RT_TOOL" "$found" "$detail"
    return 0
  fi
  printf '%s\t%s\tnone\t\tn/a\tn/a\t%s\n' "$RT_PLUGIN" "$concern" "$detail"
}

# rt_approve <root> <id>: record this clone's approval of the id's current
# record, for each concern whose command comes from repository content.
rt_approve() {
  local root="$1" id="$2" concern n=0
  rt__load "$root" "$id" || {
    printf 'resolve-tool: %s\n' "$RT__ERR" >&2
    return 1
  }
  for concern in format lint; do
    rt__key "$concern"
    rt__get "$RT__KEY" || continue
    case "$RT__GL" in team | tracked-local) ;; *) continue ;; esac
    rt__approval "$root" "$id" "$concern"
    [[ "$RT_APPROVAL" == unapproved && -n "$RT__SIG" ]] || continue
    mkdir -p "$RT__COMMON/claude-ecosystems/approved" &&
      : >"$RT__COMMON/claude-ecosystems/approved/$RT__SIG" || return 1
    n=$((n + 1))
  done
  printf 'resolve-tool: approved %s command(s) of the %s record for this clone\n' "$n" "$id"
}

if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  case "${1:-}" in
  --approve)
    [[ "${2:-}" =~ ^[a-z0-9][a-z0-9-]*$ ]] || {
      echo 'usage: resolve-tool.sh --approve <id> [<root>]' >&2
      exit 2
    }
    rt_root="${3:-$(git rev-parse --show-toplevel 2>/dev/null)}" || exit 2
    rt_approve "$rt_root" "$2"
    exit
    ;;
  *)
    echo 'usage: resolve-tool.sh --approve <id> [<root>]' >&2
    exit 2
    ;;
  esac
fi
